package handler
import("net/http";"OnCallAgent/internal/server/batch";"github.com/gin-gonic/gin")
func CreateBatch(manager *batch.Manager)gin.HandlerFunc{return func(ctx *gin.Context){var input batch.CreateInput;if err:=ctx.ShouldBindJSON(&input);err!=nil{ctx.JSON(400,gin.H{"message":err.Error()});return};job,err:=manager.Create(ctx,input);if err!=nil{ctx.JSON(422,gin.H{"message":err.Error()});return};ctx.JSON(202,job)}}
func ListBatches(manager *batch.Manager)gin.HandlerFunc{return func(ctx *gin.Context){jobs,err:=manager.Store.List(ctx);if err!=nil{ctx.JSON(500,gin.H{"message":err.Error()});return};ctx.JSON(200,gin.H{"batches":jobs})}}
func GetBatch(manager *batch.Manager)gin.HandlerFunc{return func(ctx *gin.Context){job,err:=manager.Store.Get(ctx,ctx.Param("id"));if err!=nil{ctx.JSON(500,gin.H{"message":err.Error()});return};if job==nil{ctx.JSON(404,gin.H{"message":"batch not found"});return};ctx.JSON(200,job)}}
func PauseBatch(manager *batch.Manager)gin.HandlerFunc{return func(ctx *gin.Context){job,err:=manager.Pause(ctx,ctx.Param("id"));if err!=nil{ctx.JSON(500,gin.H{"message":err.Error()});return};if job==nil{ctx.JSON(404,gin.H{"message":"batch not found"});return};ctx.JSON(200,job)}}
func ResumeBatch(manager *batch.Manager)gin.HandlerFunc{return func(ctx *gin.Context){var body struct{RetryFailed bool `json:"retry_failed"`};_ = ctx.ShouldBindJSON(&body);job,err:=manager.Resume(ctx,ctx.Param("id"),body.RetryFailed);if err!=nil{ctx.JSON(500,gin.H{"message":err.Error()});return};if job==nil{ctx.JSON(404,gin.H{"message":"batch not found"});return};ctx.JSON(http.StatusAccepted,job)}}
func DeleteBatch(manager *batch.Manager)gin.HandlerFunc{return func(ctx *gin.Context){job,err:=manager.Store.Get(ctx,ctx.Param("id"));if err!=nil{ctx.JSON(500,gin.H{"message":err.Error()});return};if job==nil{ctx.JSON(404,gin.H{"message":"batch not found"});return};if job.Status=="running"||job.Status=="pause_requested"{ctx.JSON(409,gin.H{"message":"pause the batch before deleting it"});return};if err=manager.Store.Delete(ctx,job.ID);err!=nil{ctx.JSON(500,gin.H{"message":err.Error()});return};ctx.Status(http.StatusNoContent)}}
